import React from "react";

function RunHistory({ runs }) {
  if (!runs || runs.length === 0) {
    return <p className="empty-state">No runs yet — click "Run Extraction" above.</p>;
  }

  return (
    <table className="history-table">
      <thead>
        <tr>
          <th>Date/Time</th>
          <th>Org Codes</th>
          <th>Subinventories</th>
          <th>Locators</th>
          <th>Status</th>
          <th>File</th>
        </tr>
      </thead>
      <tbody>
        {runs.map((run) => (
          <tr key={run._id}>
            <td>{new Date(run.createdAt).toLocaleString()}</td>
            <td>{run.orgCodes.join(", ")}</td>
            <td>{run.subinventoryCount}</td>
            <td>{run.locatorCount}</td>
            <td className={run.status === "success" ? "status-ok" : "status-fail"}>
              {run.status}
              {run.errorMessage ? ` — ${run.errorMessage}` : ""}
            </td>
            <td>
              {run.status === "success" && run.outputFile ? (
                <a href={`http://localhost:5050/output/${run.outputFile}`} target="_blank" rel="noreferrer">
                  Download
                </a>
              ) : (
                "—"
              )}
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

export default RunHistory;
